style.css:
@-moz-document domain("sheets.google.com") {
/* Custom background for Google Sheets */
    body {
        background: url(https://i.ibb.co/SRxqv9p/custom-pompom.png) !important;
        background-size: cover !important;
        background-position: center !important;
        opacity: 90% !important;
    }

    /* Change font settings */
    body {
        font-size: 16px !important;
        font-family: 'monospace' !important;
    }

    /* Scrollbar customization */
    .docs-gm ::-webkit-scrollbar-thumb {
        background-color: #FFFFFF;
    }

    .docs-gm ::-webkit-scrollbar-thumb:hover {
        background-color: #FFF5BD;
    }

    /* Style for tabs and toolbar items */
    .docs-sheet-tab {
        background-color: #FFF5BD !important;
        color: #333 !important;
    }

    .docs-gm .docs-horizontal-ruler, .docs-gm #kix-vertical-ruler {
        background-color: #FFF5BD !important;
        border-color: #FFFFFF !important;
    }

    /* Button and toolbar item filters */
    .docs-gm .docs-material .goog-toolbar-button-active,
    .docs-gm .docs-material .goog-toolbar-button-checked {
        background-color: url(https://i.ibb.co/SRxqv9p/custom-pompom.png) !important;
    }

    .docs-gm .docs-material .goog-toolbar-menu-button-dropdown {
        filter: hue-rotate(300deg) grayscale(0.5) brightness(1.4);
    }

    /* Style the sheet menu and buttons */
    .goog-flat-menu-button-caption {
        filter: hue-rotate(300deg) grayscale(0.5) brightness(1.4);
    }

    /* Sidebar and toolbar icon styling */
    .docs-gm .docs-gm-sidebar-icon-path {
        fill: #FFF5BD;
    }

    .docs-gm .docs-menubar .goog-control,
    .docs-title-widget {
        font-size: 16px !important;
        font-family: 'monospace' !important;
    }

    .docs-gm .goog-toolbar, .docs-gm #docs-toolbar {
        font-family: 'monospace' !important;
    }
}
